(()=>{const cases={outline:['2px solid #abc','none','solid'],inset:['0','1px auto -2px'],gap:['0','1px 2px'],background:['#fff'],'font-family':['Arial,"A,B",sans-serif'],'border-spacing':['0','2px 3px'],transform:['translateZ(50%)','perspective(-1px)','perspective(none)','matrix(1%,0,0,1,0,0)','rotate3d(1%,0,0,30deg)','skew(0)','scale(.6)','rotate(0) translateY(0)','rotate(calc(10deg + 20deg))','scale(calc(1 + 2))','rotate(calc(1rad + 2rad))','translate(calc(1px + 2px),4px)','scale(calc(1px + 2px))','rotate(calc(1 + 2))','scale(50%)','translate(-2px,0)','var(--x, scale(.6))'],opacity:['.8','150%','-1'],color:['#abc','red','rgba(1,2,3,.5)'],fill:['#abc','none','url("#x") red'],stroke:['#fff','none'],'box-shadow':['10% 0 red','0 0 -1px red','inset 0 0 0#abc','1px 2px red','0 1px 2px 3px rgba(0,0,0,.2),inset 1px 0 blue'],'text-shadow':['0 1px red'],'transform-origin':['center','top','left bottom','20%','0 0'], 'grid-area':['1/1','a / b / c / d'],'stroke-dasharray':['-1,2','bogus','0,100,0','1 2 3']};const out={};for(const [name,values]of Object.entries(cases))out[name]=values.map(value=>{const s=document.createElement('div').style;s.setProperty(name,value);return s.cssText});const opacityNode=document.createElement('div');document.body.append(opacityNode);out.opacityComputed=['150%','-1','.8'].map(v=>{opacityNode.style.opacity=v;return getComputedStyle(opacityNode).opacity});opacityNode.remove();const sheet=new CSSStyleSheet();sheet.replaceSync('.a>.b+.c~.d{stroke-width:2px;color:red;stroke-width:3px}');out.rule=sheet.cssRules[0].cssText;return out})()